 # Seed script for empty library schema; explicit identity inserts for deterministic IDs; NOT a production load.
 stmt=['-- DATOS FICTICIOS SOLO PARA BASE DE PRACTICAS VACIA. NO USAR EN PRODUCCION.', '-- Ejecutar despues de schema_sqlserver.sql, en BibliotecaEscolar_U3.', '-- Este script RECHAZA su ejecucion si alguna tabla del proyecto ya tiene registros.', "IF DB_ID(N'BibliotecaEscolar_U3') IS NULL THROW 50003, N'Base de datos inexistente.', 1;",'GO','USE [BibliotecaEscolar_U3];','GO','SET XACT_ABORT ON;', 'BEGIN TRANSACTION;']
 for t in TABLES:
  stmt.append('IF EXISTS (SELECT 1 FROM biblioteca.'+t+') THROW 50004, N\'La base ya contiene datos; se cancela la carga demo.\', 1;')
 identities=['persona','autor','coleccion','ejemplar','prestamo','incidencia']
 for t in TABLES:
  if t in identities: stmt.append('SET IDENTITY_INSERT biblioteca.'+t+' ON;')
  cols=TABLES[t]
  for vals in DATA[t]:
   def lit(x):
    return 'NULL' if x is None else ("N'"+str(x).replace("'","''")+"'" if isinstance(x,str) else str(x))
   stmt.append('INSERT INTO biblioteca.'+t+' ('+', '.join(cols)+') VALUES ('+', '.join(lit(v) for v in vals)+');')
  if t in identities: stmt.append('SET IDENTITY_INSERT biblioteca.'+t+' OFF;')
 stmt+=['COMMIT TRANSACTION;','PRINT N\'Datos ficticios insertados. Ejecute consultas_sqlserver.sql.\';','GO']
 (ROOT/'Tarea_5_2'/'datos_demo_sqlserver.sql').write_text('\n'.join(stmt),encoding='utf-8-sig')
